sys_security_acl.script:
var gr = new GlideRecord('x_illu2_illumio_illumio_pce_field_mapping');
gr.query();
var fields = ['application', 'environment', 'role', 'location', 'ip_address', 'ip_address_2', 'ip_address_3','ip_address_4','ip_address_5','ip_address_6'];

var nonEmptyFields = [];
while(gr.next()){
    for (var i = 0; i < fields.length; i++) {
        if(!gs.nil(gr.getValue(fields[i]))){
            nonEmptyFields.push(fields[i]);
        }
    }
}

if(fields.length == nonEmptyFields.length){
    answer = false;
} else {
    answer = true;
}
